cases.stdin:
f() { local x=1; if [ 1 ]; then echo "a b"; fi; for i in 1 2; do :; done; }
declare -f f

g() { if [ 1 ]; then echo a; echo b; else echo c; fi; }
declare -f g

h() { while :; do break; done; { echo a; }; case x in a) echo b;; esac; }
declare -f h

i() { until :; do echo x; done; ( echo s; echo t ); }
declare -f i

f() {
  case "$1" in
    a|b|c) echo abc;;
    (d|e) echo de;;
    single) echo one;;
    *) ;;
  esac
}
declare -f f

g() { echo original; }
readonly -f g
echo "status: $?"
g() { echo redefined; }
g
readonly -f nosuchfn

myfunc() { echo hi; }
declare -t myfunc
declare -f myfunc | head -1
